#!/data/data/com.termux/files/usr/bin/bash
set -Eeuo pipefail
cd "$HOME/companyos"
STAMP="$(date +%Y%m%d_%H%M%S)"
BK=".companyos_backups/request_stop_v26_$STAMP"
mkdir -p "$BK"
cp -a companyos/runtime/service_supervisor.py "$BK/"

echo "" | base64 -d > "$PREFIX/tmp/companyos_v26_patch.py"
python "$PREFIX/tmp/companyos_v26_patch.py"
rm -f "$PREFIX/tmp/companyos_v26_patch.py"

echo "" | base64 -d > scripts/companyos_verify_stop_v26
chmod +x scripts/companyos_verify_stop_v26

scripts/companyos_verify_stop_v26 | tee .companyos_runtime/request_stop_v26.log

git add companyos/runtime/service_supervisor.py scripts/companyos_verify_stop_v26
git diff --cached --quiet || git commit -m "Target supervisor stop requests to current PID"
BRANCH="$(git branch --show-current)"
[ -n "$BRANCH" ] && git push origin "$BRANCH" || true

echo "BACKUP=$BK"
echo "COMPANYOS_REQUEST_STOP_PID_TARGET_V26=PASS"
